use serde_json::{Value, Error as JsonError};

pub fn solve(input: Value) -> Result<Value, JsonError> {
    match input {
        Value::String(s) => Ok(Value::String(apply_rot13(s))),
        Value::Array(arr) => Ok(Value::Array(arr.into_iter().map(apply_rot13).collect())),
        _ => Ok(input),
    }
}

fn apply_rot13(s: String) -> String {
    s.chars()
        .map(|c| {
            if c.is_ascii_alphabetic() {
                let base = if c.is_ascii_lowercase() { 'a' } else { 'A' } as u8;
                let offset = c as u8 - base;
                let new_offset = (offset + 13) % 26;
                (base + new_offset) as char
            } else {
                c
            }
        })
        .collect()
}
